/* GENERATED from data/glossary.json by scripts/build-data.mjs — do not edit. */
(function (root) {
  var NS = (root.CollectorLens = root.CollectorLens || {});
  NS.GLOSSARY = {"version":1,"updated":"2026-10-09","entries":[{"id":"cond_new_unused","ja":["新品、未使用","新品・未使用"],"en":"Platform grade: New / unused","explain":"Top grade on the Mercari/Yahoo/Rakuma condition scale. The seller picks the grade themselves, so check photos and the description for storage age or missing items.","genre":["general"],"category":"rank","risk":"positive","reviewed":true},{"id":"cond_near_unused","ja":["未使用に近い"],"en":"Platform grade: Like new","explain":"Second grade on the platform scale: used only briefly or very lightly. Seller-chosen, not inspected by the platform.","genre":["general"],"category":"rank","risk":"low","reviewed":true},{"id":"cond_no_noticeable_marks","ja":["目立った傷や汚れなし"],"en":"Platform grade: No noticeable marks","explain":"Middle-upper platform grade: used, but no obvious scratches or stains at a glance. Small marks and internal issues (e.g. lens haze) can still exist.","genre":["general"],"category":"rank","risk":"low","reviewed":true},{"id":"cond_some_marks","ja":["やや傷や汚れあり"],"en":"Platform grade: Some marks","explain":"Platform grade meaning visible but minor scratches or dirt. Read the description and zoom into photos to see where and how bad.","genre":["general"],"category":"rank","risk":"medium","reviewed":true},{"id":"cond_marks","ja":["傷や汚れあり"],"en":"Platform grade: Scratches / stains","explain":"Platform grade for clearly worn items with obvious scratches or stains. Expect cosmetic wear; function is not implied either way.","genre":["general"],"category":"rank","risk":"medium","reviewed":true},{"id":"cond_poor","ja":["全体的に状態が悪い"],"en":"Platform grade: Poor overall","explain":"Lowest platform grade. Usually heavy wear or damage, often close to junk. Assume repairs may be needed.","genre":["general"],"category":"rank","risk":"high","reviewed":true},{"id":"shinpin","ja":["新品"],"en":"New","explain":"Brand new. For vintage items this may really mean old unsold stock; check whether it was stored for years.","genre":["general"],"category":"condition","risk":"positive","reviewed":true},{"id":"mishiyou","ja":["未使用","未使用品"],"en":"Unused","explain":"Never used, but not necessarily new in box. Old unused cameras/watches can still have dried lubricants or storage damage.","genre":["general"],"category":"condition","risk":"positive","reviewed":true},{"id":"chuko","ja":["中古","中古品"],"en":"Used / second-hand","explain":"Pre-owned item. On its own it says nothing about condition; look for the grade and the defect notes.","genre":["general"],"category":"condition","risk":"info","reviewed":true},{"id":"shinkohin","ja":["新古品"],"en":"New old stock / unused old item","explain":"Unused but not sold as new (old stock or a gift never used). Age-related issues such as dried grease or dead batteries are still possible.","genre":["general"],"category":"condition","risk":"low","reviewed":true},{"id":"deadstock","ja":["デッドストック"],"en":"Dead stock (old unsold stock)","explain":"Old stock never sold or used. Desirable to collectors, but long storage can cause hardened oils, seals or straps decaying.","genre":["general"],"category":"condition","risk":"low","reviewed":true},{"id":"bihin","ja":["美品"],"en":"Good-looking (fine) condition","explain":"Literally 'beautiful item': clean with only light wear. Very widely and loosely used by private sellers; it describes looks, not function.","genre":["general"],"category":"rank","risk":"low","reviewed":true},{"id":"gokubihin","ja":["極美品"],"en":"Excellent+ (near mint)","explain":"Rank above 美品 (bihin, \"fine\"): near mint with minimal wear. Shops use it fairly consistently; private sellers may be generous.","genre":["general"],"category":"rank","risk":"positive","reviewed":true},{"id":"choubihin","ja":["超美品"],"en":"Excellent (very fine)","explain":"'Super fine' – roughly between 美品 (\"fine\") and 極美品 (\"near mint\"). Not standardised; compare with the photos.","genre":["general"],"category":"rank","risk":"positive","reviewed":true},{"id":"ryouhin","ja":["良品"],"en":"Good (normal wear)","explain":"Shop rank below 美品 (\"fine\"): normal signs of use. Also used loosely to mean simply 'a good item'.","genre":["general"],"category":"rank","risk":"low","reviewed":true},{"id":"namihin","ja":["並品"],"en":"Average (noticeable wear)","explain":"Camera-shop rank below 良品 (\"good\"): clearly used with visible wear. Usually still functional when sold by a shop, but check the notes.","genre":["general"],"category":"rank","risk":"medium","reviewed":true},{"id":"shiyoukan","ja":["使用感あり","使用感有り","使用感があります"],"en":"Shows signs of use","explain":"The item shows visible wear from use. How much varies a lot; check the photos.","genre":["general"],"category":"condition","risk":"medium","reviewed":true},{"id":"keinen_rekka","ja":["経年劣化","経年による"],"en":"Age-related wear","explain":"Deterioration from age (discoloured materials, worn finish, hardened parts). Sellers often use it to explain away defects; ask what exactly is affected.","genre":["general"],"category":"condition","risk":"medium","reviewed":true},{"id":"kokizu","ja":["小傷","小キズ","細かな傷","細かいキズ","小さな傷"],"en":"Minor scratches","explain":"Small or fine scratches. Usually cosmetic, but on lens glass or a watch crystal location matters.","genre":["general"],"category":"defect","risk":"low","reviewed":true},{"id":"sure","ja":["スレ傷","スレキズ","擦れ","スレあり"],"en":"Scuffs / rub marks","explain":"Rubbing wear, typically on edges, corners or bracelet surfaces. Cosmetic.","genre":["general"],"category":"defect","risk":"low","reviewed":true},{"id":"dakon","ja":["打痕"],"en":"Dent / impact mark","explain":"Mark from a knock or drop. On a camera or watch case it can mean an impact that also affected the internals.","genre":["general"],"category":"defect","risk":"medium","reviewed":true},{"id":"fushoku","ja":["腐食"],"en":"Corrosion","explain":"Corrosion of metal or other parts (battery contacts, prism silvering, watch case). Can be cosmetic or a serious functional problem depending on where.","genre":["general"],"category":"defect","risk":"high","reviewed":true},{"id":"ekimore","ja":["液漏れ","液漏れ跡","電池液漏れ"],"en":"Battery leakage","explain":"A battery leaked inside. Corrosion can damage contacts and circuits; often a repair job even if cleaned.","genre":["general"],"category":"defect","risk":"high","reviewed":true},{"id":"nan_ari","ja":["難あり","難有り"],"en":"Has a problem / flawed","explain":"The seller admits a defect. Read carefully what the problem is; it may be cosmetic or functional.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"wake_ari","ja":["訳あり","訳有り","ワケあり","わけあり"],"en":"Sold with a catch","explain":"'There is a reason' – discounted because of a flaw, missing part or unclear background. Find out what the reason is before buying.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"genjouhin","ja":["現状品"],"en":"Sold as-is","explain":"Sold in its current state without checking or repair. Usually no returns for defects; treat as untested.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"genjou_watashi","ja":["現状渡し","現状でのお渡し","現状のまま"],"en":"As-is handover","explain":"Handed over as-is with no repairs or guarantees. Defects found later are typically your problem.","genre":["general"],"category":"return","risk":"high","reviewed":true},{"id":"junk","ja":["ジャンク","ジャンク品","ジャンク扱い"],"en":"Junk (sold as-is)","explain":"Sold as broken or untested with no returns. Can be anything from fully working to parts-only; price it as non-working.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"buhintori","ja":["部品取り","部品取り用"],"en":"For parts only","explain":"Sold as a parts donor. Expect it not to work and possibly not to be repairable.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"dousa_mikakunin","ja":["動作未確認"],"en":"Function not tested","explain":"The seller has not checked if it works. In practice often means it does not work or they suspect so; treat as junk.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"mikakunin","ja":["未確認"],"en":"Not checked","explain":"Something was not verified – read what (function, authenticity, parts). Untested items should be priced as faulty.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"dousa_kakunin_zumi","ja":["動作確認済み","動作確認済","動作品","動作OK"],"en":"Tested and working","explain":"Seller says it works. Check how it was tested; a basic check may miss issues like inaccurate shutter speeds or poor timekeeping.","genre":["general"],"category":"condition","risk":"positive","reviewed":true},{"id":"tsuuden_only","ja":["通電確認のみ","通電のみ確認"],"en":"Power-on check only","explain":"Only confirmed that it powers on. Other functions were not tested.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"fudou","ja":["不動","不動品"],"en":"Not working","explain":"Does not work at all. Repair cost for vintage cameras/watches can easily exceed the item price.","genre":["general"],"category":"condition","risk":"high","reviewed":true},{"id":"hoshou_nashi","ja":["保証なし","保証無し"],"en":"No warranty","explain":"No warranty is offered. Once delivered, defects are generally your responsibility; often paired with no returns.","genre":["general"],"category":"return","risk":"high","reviewed":true},{"id":"ncnr","ja":["ノークレームノーリターン","ノークレーム・ノーリターン","NCNR","ノンクレームノンリターン","ノンクレーム・ノンリターン"],"en":"No claims, no returns (NCNR)","explain":"Seller refuses complaints and returns. Common on Yahoo! Auctions; for an overseas buyer via a proxy, assume you cannot return the item.","genre":["general"],"category":"return","risk":"high","reviewed":true},{"id":"henpin_fuka","ja":["返品不可","返品はお受けできません","返品・返金不可","ノーリターン"],"en":"No returns","explain":"Returns are not accepted. Ask questions before bidding or buying.","genre":["general"],"category":"return","risk":"high","reviewed":true},{"id":"henpin_ka","ja":["返品可","返品可能","返品OK"],"en":"Returns accepted","explain":"The seller accepts returns, often within a stated period. Check conditions; return shipping from abroad may be costly.","genre":["general"],"category":"return","risk":"positive","reviewed":true},{"id":"shokifuryo","ja":["初期不良対応","初期不良のみ対応","初期不良のみ返品可"],"en":"Dead-on-arrival support","explain":"The seller will deal with defects found right on arrival, usually within a few days. Through a proxy service, that window may pass before you receive it.","genre":["general"],"category":"return","risk":"positive","reviewed":true},{"id":"shiroto_hokan","ja":["素人保管"],"en":"Stored by an amateur","explain":"Stored by a non-expert, not in proper conditions. Often a hint of possible mould, haze or storage damage.","genre":["general"],"category":"seller","risk":"medium","reviewed":true},{"id":"kuwashikunai","ja":["素人なので詳しくありません","詳しくありません","詳しくないので","詳しくないため","知識がないため","素人のため"],"en":"Seller is not knowledgeable","explain":"Seller says they don't know the item well. It shifts responsibility to you; descriptions may be incomplete or wrong.","genre":["general"],"category":"seller","risk":"medium","reviewed":true},{"id":"shashin_handan","ja":["写真でご判断ください","写真でご判断下さい","画像でご判断ください","画像でご判断下さい","写真にてご判断ください","画像にてご判断ください"],"en":"Judge from the photos","explain":"The seller won't describe condition further. Anything not visible in the photos is not covered; ask for extra photos if needed.","genre":["general"],"category":"seller","risk":"medium","reviewed":true},{"id":"shinkeishitsu","ja":["神経質な方はご遠慮ください","神経質な方はご遠慮下さい","神経質な方は入札をご遠慮ください","神経質な方はお控えください"],"en":"Not for picky buyers","explain":"'Fussy buyers please avoid.' Usually means there are flaws the seller doesn't want complaints about.","genre":["general"],"category":"seller","risk":"medium","reviewed":true},{"id":"chuko_rikai","ja":["中古品にご理解のある方","中古品にご理解ある方","中古にご理解のある方","中古品であることをご理解の上"],"en":"Buyers who accept used goods","explain":"A disclaimer that wear and minor issues should be expected and won't be accepted as complaints.","genre":["general"],"category":"seller","risk":"medium","reviewed":true},{"id":"jitaku_hokan","ja":["自宅保管","自宅保管品"],"en":"Stored at home","explain":"Kept in a private home, not a controlled environment. Japan's humidity makes mould in lenses and rust a real possibility.","genre":["general"],"category":"seller","risk":"low","reviewed":true},{"id":"choki_hokan","ja":["長期保管","長期保管品"],"en":"Long-term storage","explain":"Unused for a long time. Lubricants may have dried or migrated, light seals and batteries may have degraded.","genre":["general"],"category":"condition","risk":"medium","reviewed":true},{"id":"kitsuensha","ja":["喫煙者","喫煙環境"],"en":"Smoking household","explain":"Item came from a home with a smoker. Smoke odour and residue can be present, including on lens elements.","genre":["general"],"category":"seller","risk":"low","reviewed":true},{"id":"kinen","ja":["禁煙環境","非喫煙者"],"en":"Non-smoking household","explain":"Item kept in a smoke-free home.","genre":["general"],"category":"seller","risk":"positive","reviewed":true},{"id":"pet","ja":["ペットあり","ペット有り","ペットを飼っています"],"en":"Pets in household","explain":"Home with pets. Pet hair or odour may be present.","genre":["general"],"category":"seller","risk":"low","reviewed":true},{"id":"shingan_fumei","ja":["真贋不明","真贋未確認","真偽不明"],"en":"Authenticity unknown","explain":"Seller does not vouch that it is genuine. Often a way to list fakes without claiming they are real; assume it may not be genuine.","genre":["general"],"category":"authenticity","risk":"high","reviewed":true},{"id":"honmono_hoshou_nashi","ja":["本物保証なし","本物の保証はできません"],"en":"No authenticity guarantee","explain":"The seller will not guarantee the item is genuine. Treat as possibly fake.","genre":["general"],"category":"authenticity","risk":"high","reviewed":true},{"id":"kanteizumi","ja":["鑑定済み","鑑定済"],"en":"Authenticated (appraised)","explain":"Seller says it was checked for authenticity. Ask who appraised it; a shop or professional appraisal is worth more than a claim.","genre":["general"],"category":"authenticity","risk":"positive","reviewed":true},{"id":"seikihin","ja":["正規品"],"en":"Genuine product","explain":"Claims the item is a genuine brand product. A claim only; check serials, photos and provenance.","genre":["general"],"category":"authenticity","risk":"low","reviewed":true},{"id":"copy","ja":["コピー品","コピー商品"],"en":"Counterfeit / copy","explain":"A fake. Importing counterfeits can be illegal in many countries and they may be seized at customs.","genre":["general"],"category":"authenticity","risk":"high","reviewed":true},{"id":"replica","ja":["レプリカ"],"en":"Replica","explain":"A reproduction, not the original brand item. For branded goods this generally means a fake.","genre":["general"],"category":"authenticity","risk":"high","reviewed":true},{"id":"super_copy","ja":["スーパーコピー"],"en":"'Super copy' (high-grade fake)","explain":"Slang for a high-quality counterfeit. It is not genuine regardless of how good it looks.","genre":["general"],"category":"authenticity","risk":"high","reviewed":true},{"id":"n_hin","ja":["N品","N級品"],"en":"N-grade (fake, slang)","explain":"Slang used by sellers of counterfeits to mean a high-grade copy. Not genuine.","genre":["general"],"category":"authenticity","risk":"high","reviewed":true},{"id":"no_brand","ja":["ノーブランド","ノンブランド"],"en":"Unbranded","explain":"No brand or unknown maker. If the item looks like a famous brand, it may be a copy or homage.","genre":["general"],"category":"authenticity","risk":"medium","reviewed":true},{"id":"shagaihin","ja":["社外品"],"en":"Aftermarket / third-party","explain":"Not made by the original manufacturer (part, accessory or the item itself). Usually lowers collector value.","genre":["general"],"category":"part","risk":"medium","reviewed":true},{"id":"junsei","ja":["純正","純正品"],"en":"Genuine OEM (original maker)","explain":"Made by the original manufacturer. Does not by itself mean original to this particular item.","genre":["general"],"category":"part","risk":"positive","reviewed":true},{"id":"heikou_yunyu","ja":["並行輸入","並行輸入品","並行品"],"en":"Grey import","explain":"Genuine item imported outside the official distributor. Japanese official service or warranty may not apply.","genre":["general"],"category":"authenticity","risk":"info","reviewed":true},{"id":"kokunai_seiki","ja":["国内正規品","国内正規"],"en":"Japan official (domestic) item","explain":"Sold through the official Japanese distributor. Usually comes with domestic warranty paperwork if complete.","genre":["general"],"category":"authenticity","risk":"positive","reviewed":true},{"id":"antique","ja":["アンティーク","ヴィンテージ","ビンテージ"],"en":"Antique / vintage","explain":"Old item. Used loosely; age alone says nothing about condition or originality.","genre":["general"],"category":"condition","risk":"info","reviewed":true},{"id":"fuzokuhin_nashi","ja":["付属品なし","付属品無し"],"en":"No accessories","explain":"Comes without box, papers, caps or other accessories. Lowers collector value.","genre":["general"],"category":"accessory","risk":"low","reviewed":true},{"id":"fuzokuhin_kanbi","ja":["付属品完備","付属品完品"],"en":"All accessories included","explain":"All accessories said to be present. Check the photos against what the item originally came with.","genre":["general"],"category":"accessory","risk":"positive","reviewed":true},{"id":"keppin","ja":["欠品","欠品あり","欠品有り"],"en":"Missing parts / items","explain":"Something is missing. Check whether it is an accessory or a functional part.","genre":["general"],"category":"accessory","risk":"medium","reviewed":true},{"id":"hako_nashi","ja":["箱なし","箱無し","箱無"],"en":"No box","explain":"Sold without the box. Matters for collector value, especially for watches.","genre":["general"],"category":"accessory","risk":"low","reviewed":true},{"id":"motobako","ja":["元箱","元箱付き","箱付き"],"en":"Original box","explain":"Comes with the original box. Check it is the box for this model and not a generic replacement.","genre":["general"],"category":"accessory","risk":"positive","reviewed":true},{"id":"hoshousho","ja":["保証書","保証書付き"],"en":"Warranty certificate","explain":"Warranty paper. For vintage items it is usually expired but helps provenance; check that dates and numbers match.","genre":["general"],"category":"accessory","risk":"info","reviewed":true},{"id":"manual","ja":["取扱説明書","取説","説明書","使用説明書"],"en":"Instruction manual","explain":"The instruction manual. Nice to have; not important for function.","genre":["general"],"category":"accessory","risk":"info","reviewed":true},{"id":"honntai_nomi","ja":["本体のみ"],"en":"Item only (no accessories)","explain":"Only the item itself; no box, papers, strap, caps etc.","genre":["general"],"category":"accessory","risk":"low","reviewed":true},{"id":"ichien_start","ja":["1円スタート","1円〜"],"en":"Starts at 1 yen","explain":"Yahoo! Auctions listing starting at 1 yen. A sales tactic; the final price can be high and many such listings are junk or as-is.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"sokketsu","ja":["即決"],"en":"Buy-it-now price","explain":"Yahoo! Auctions fixed 'buy now' price that ends the auction immediately.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"soku_kounyu","ja":["即購入可","即購入OK","即購入歓迎"],"en":"Instant purchase OK","explain":"Mercari: you can buy without asking first.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"soku_kounyu_fuka","ja":["即購入不可","即購入禁止"],"en":"Comment before buying","explain":"Mercari: seller asks you to comment before purchasing. Buying straight away may get cancelled.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"kaigai_hassou_fuka","ja":["海外発送不可","海外発送はしておりません"],"en":"No international shipping","explain":"Seller ships only within Japan. You would need a proxy or forwarding service.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"tokumei","ja":["匿名配送"],"en":"Anonymous shipping","explain":"Platform shipping where buyer and seller addresses are hidden. Domestic Japan only.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"souryou_komi","ja":["送料込み","送料無料"],"en":"Shipping included","explain":"Domestic Japanese shipping is included. International or proxy shipping is extra.","genre":["general"],"category":"service","risk":"info","reviewed":true},{"id":"nikoichi","ja":["ニコイチ"],"en":"Two-into-one (built from 2 units)","explain":"Made by combining parts of two units into one. Not original; collector value is lower and parts may be mismatched.","genre":["general","camera","watch"],"category":"authenticity","risk":"high","reviewed":true},{"id":"kataban","ja":["型番","Ref.","リファレンス"],"en":"Model / reference number","explain":"Model or reference number. Check that it matches the dial, case and movement shown.","genre":["general","watch"],"category":"part","risk":"info","reviewed":true},{"id":"kikaishiki","ja":["機械式"],"en":"Mechanical","explain":"Mechanical (spring/gear driven) camera shutter or watch movement. Works without a battery but needs periodic servicing.","genre":["camera","watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"bunkai_ato","ja":["分解跡","分解歴あり","分解歴有り","カニ目傷"],"en":"Signs of disassembly","explain":"Marks showing it has been opened (scratched screws, tool marks on lens spanner slots). Could be pro service or an amateur attempt.","genre":["camera","watch"],"category":"defect","risk":"medium","reviewed":true},{"id":"yellowing","ja":["黄変","ヤケ","黄ばみ"],"en":"Yellowing / discolouration","explain":"Lenses: yellow tint (often thorium glass; UV light can reduce it). Bodies/leather: sun fading. Watches: dial or lume ageing, which some collectors like.","genre":["camera","watch"],"category":"defect","risk":"medium","reviewed":true},{"id":"ura_buta","ja":["裏蓋","裏ぶた"],"en":"Back cover / caseback","explain":"Camera back door or watch caseback. On watches, check engravings and serial against the model.","genre":["camera","watch"],"category":"part","risk":"info","reviewed":true},{"id":"oh_done","ja":["OH済み","OH済","オーバーホール済み","オーバーホール済"],"en":"Serviced (overhauled)","explain":"Was overhauled. Ask when and by whom; a recent shop service with a receipt is worth much more than a vague claim.","genre":["camera","watch"],"category":"service","risk":"positive","reviewed":true},{"id":"denchi_kire","ja":["電池切れ"],"en":"Battery dead","explain":"Battery is dead so it was not tested. It may only need a battery, or it may be faulty; price as untested.","genre":["camera","watch"],"category":"condition","risk":"medium","reviewed":true},{"id":"parts_replaced","ja":["部品交換","パーツ交換","部品交換歴あり"],"en":"Parts replaced","explain":"Some parts have been replaced. Ask whether they were genuine parts; non-original parts lower collector value.","genre":["camera","watch"],"category":"part","risk":"medium","reviewed":true},{"id":"kabi","ja":["カビ","かび","黴"],"en":"Fungus (lens mould)","explain":"Fungus growth inside the lens. It can etch coatings and spread; removal needs disassembly and may leave marks.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"kumori","ja":["くもり","クモリ","曇り"],"en":"Haze","explain":"Haze inside the lens, which lowers contrast. Light haze may clean off; haze in cemented groups or glass often cannot.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"balsam","ja":["バルサム切れ"],"en":"Balsam separation","explain":"The cement between bonded lens elements has separated. Repair requires re-cementing and is rarely worthwhile.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"fukikizu","ja":["拭き傷","拭きキズ","ふき傷"],"en":"Cleaning marks","explain":"Fine scratches on glass from wiping. Usually little effect on images unless heavy; can cause flare.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"dust","ja":["チリ","ホコリ","埃","塵","チリ混入","ホコリ混入"],"en":"Dust inside the lens","explain":"Dust specks inside the lens. Small amounts are normal in old lenses and rarely affect images.","genre":["camera"],"category":"defect","risk":"low","reviewed":true},{"id":"maedama","ja":["前玉"],"en":"Front element","explain":"The front lens element. Scratches or coating damage here are visible but may affect images less than on the rear element.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"nakadama","ja":["中玉"],"en":"Inner element(s)","explain":"Lens elements inside the barrel. Problems here (haze, fungus) need disassembly to fix.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"atodama","ja":["後玉"],"en":"Rear element","explain":"The rear lens element. Damage here affects images more than on the front element.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"coating","ja":["コーティング"],"en":"Lens coating","explain":"The anti-reflection coating on the glass. Usually mentioned with damage or wear.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"coating_damage","ja":["コーティング剥がれ","コーティングハゲ","コーティングムラ"],"en":"Coating damage","explain":"Coating is worn or peeling. May increase flare and reduce contrast.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"lens_scratch","ja":["レンズ傷","レンズキズ","レンズに傷"],"en":"Scratch on lens glass","explain":"Scratch on the glass. Its effect depends on size and position; rear-element scratches matter more.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"shibori_hane","ja":["絞り羽根","絞り羽"],"en":"Aperture blades","explain":"Aperture blades. Check they move snappily and are free of oil.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"abura","ja":["油滲み","油染み","油にじみ","油シミ","油浮き"],"en":"Oil on aperture blades","explain":"Lubricant has migrated onto the aperture blades, which can make them stick. Fix requires cleaning the lens.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"nebari","ja":["粘り","絞り粘り","スロー粘り","粘りあり"],"en":"Sticking / sluggish","explain":"Aperture or slow shutter speeds move sluggishly, usually from old oil. Exposures will be wrong until serviced.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"kataboke","ja":["片ボケ"],"en":"Decentred (one side blurry)","explain":"One side of the image is blurrier than the other, often from a knock or bad reassembly. Hard to see in photos of the lens itself.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"utsuri_eikyou_nashi","ja":["写りに影響なし","写りに影響ありません","撮影に影響なし","撮影に影響ありません"],"en":"No effect on images (claimed)","explain":"Seller claims the defect does not affect pictures. Often a guess, not a test; ask for sample photos.","genre":["camera"],"category":"seller","risk":"low","reviewed":true},{"id":"kougaku_ryoukou","ja":["光学良好","光学系良好"],"en":"Optics good","explain":"The glass is said to be clear. May still allow small dust or light marks.","genre":["camera"],"category":"condition","risk":"positive","reviewed":true},{"id":"kougaku_gokujou","ja":["光学極上","光学系極上"],"en":"Optics excellent","explain":"Optics described as excellent: clean, no haze or fungus.","genre":["camera"],"category":"condition","risk":"positive","reviewed":true},{"id":"gaikan","ja":["外観"],"en":"Exterior / cosmetics","explain":"Refers to the outside condition only (e.g. 外観美品, \"body looks fine\"). Says nothing about optics or function.","genre":["camera"],"category":"condition","risk":"info","reviewed":true},{"id":"shutter","ja":["シャッター"],"en":"Shutter","explain":"Shutter mechanism. Check whether all speeds are tested, not just whether it fires.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"shutter_fault","ja":["シャッター不良","シャッター切れず","シャッターが切れない","シャッター切れません"],"en":"Shutter not working","explain":"The shutter will not fire or is faulty. Requires repair.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"shutter_all_ok","ja":["全速OK","全速確認","シャッター全速OK","全速作動"],"en":"All shutter speeds work","explain":"All speeds fire. Often checked by ear, not with a tester, so accuracy is not guaranteed.","genre":["camera"],"category":"condition","risk":"positive","reviewed":true},{"id":"kara_shutter","ja":["空シャッター","空シャッターのみ","空写し"],"en":"Fired without film","explain":"Shutter fired without film. Shows it moves, not that exposures or film transport are correct.","genre":["camera"],"category":"condition","risk":"medium","reviewed":true},{"id":"slow_shutter","ja":["スローシャッター","スロー域"],"en":"Slow shutter speeds","explain":"The slow speeds (about 1s–1/30). These are the first to stick or run long on old mechanical cameras.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"shutter_maku","ja":["シャッター幕","布幕","チタン幕"],"en":"Shutter curtain","explain":"Focal-plane shutter curtain (cloth or titanium foil). Check for holes, wrinkles or light leaks.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"maku_damage","ja":["幕穴","幕ヨレ","幕のヨレ","幕シワ"],"en":"Shutter curtain damage","explain":"Holes or wrinkles in the shutter curtain. Causes light leaks or uneven exposure; replacement is a costly repair.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"saki_ato_maku","ja":["先幕","後幕"],"en":"Front / rear curtain","explain":"The first and second shutter curtains. Problems with either cause uneven or failed exposures.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"shutter_naki","ja":["シャッター鳴き"],"en":"Shutter squeal","explain":"Squeaking noise when firing, a known issue on some models (e.g. Canon A-series). Needs lubrication.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"roshutsukei","ja":["露出計"],"en":"Light meter","explain":"Built-in exposure meter. Check whether it works and is accurate.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"roshutsukei_fudou","ja":["露出計不動","露出計動かず","メーター不動","露出計NG"],"en":"Light meter dead","explain":"Built-in meter does not work. Camera may still shoot with a handheld meter; repair may be hard.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"roshutsukei_ok","ja":["露出計動作","露出計作動","露出計OK"],"en":"Light meter works","explain":"Meter responds. Accuracy may still be off, especially with modern replacement batteries.","genre":["camera"],"category":"condition","risk":"positive","reviewed":true},{"id":"selenium","ja":["セレン","セレン露出計"],"en":"Selenium meter","explain":"Battery-free selenium-cell meter on older cameras. These cells degrade with age and are often weak or dead.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"mercury_battery","ja":["水銀電池"],"en":"Mercury battery","explain":"Older cameras designed for 1.35V mercury cells, now discontinued. Modern substitutes may give wrong meter readings without an adapter.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"molt","ja":["モルト","モルト劣化","モルトプレーン"],"en":"Light seals (foam)","explain":"Foam light seals that crumble with age. Replacement is cheap and routine, but degraded seals cause light leaks.","genre":["camera"],"category":"part","risk":"medium","reviewed":true},{"id":"mirror","ja":["ミラー"],"en":"Mirror (SLR)","explain":"Reflex mirror. Scratches on it don't affect images, only the viewfinder.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"prism","ja":["プリズム","ペンタプリズム"],"en":"Prism","explain":"Viewfinder pentaprism. Desilvering/corrosion shows as dark lines or spots in the finder.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"prism_corrosion","ja":["プリズム腐食","プリズムの腐食","プリズム劣化"],"en":"Prism desilvering","explain":"The prism's silvering is deteriorating, often from the foam above it. Visible in the viewfinder; costly to fix.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"penta_dent","ja":["ペンタ部凹み","ペンタ凹み","ペンタ部へこみ","ペンタ部打痕"],"en":"Dented prism housing","explain":"Dent on the top prism hump, a sign the camera was dropped. Internal alignment may be affected.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"finder","ja":["ファインダー","ファインダー内"],"en":"Viewfinder","explain":"The viewfinder. Dust or marks inside it usually don't affect images.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"nijuuzou","ja":["二重像"],"en":"Rangefinder double image","explain":"The overlapping image used to focus a rangefinder. Check it is bright and aligns at infinity.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"nijuuzou_zure","ja":["二重像ズレ","二重像のズレ","距離計ズレ"],"en":"Rangefinder misaligned","explain":"Rangefinder is out of alignment, so focus will be off. Usually adjustable by a repairer.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"nijuuzou_usui","ja":["二重像が薄い","二重像薄い","二重像薄め"],"en":"Faint rangefinder image","explain":"Double image is dim, often from deteriorated mirror coatings. Makes focusing harder.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"kyorikei","ja":["距離計","距離計連動"],"en":"Rangefinder (distance meter)","explain":"Rangefinder focusing mechanism.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"helicoid","ja":["ヘリコイド"],"en":"Helicoid (focusing thread)","explain":"The threaded focusing mechanism of a lens.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"helicoid_heavy","ja":["ヘリコイド重い","ヘリコイドが重い","ヘリコイド重め","ヘリコイド硬い","グリス切れ","グリス抜け"],"en":"Stiff focus / dried grease","explain":"Focusing is stiff or uneven, usually from dried grease. Fixable by regreasing but adds cost.","genre":["camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"af","ja":["AF","オートフォーカス"],"en":"Autofocus (AF)","explain":"Autofocus lens or camera. Check that AF works, not just manual focus.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"mf","ja":["MF","マニュアルフォーカス"],"en":"Manual focus (MF)","explain":"Manual-focus lens or camera.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"rangefinder","ja":["レンジファインダー","レンジファインダーカメラ"],"en":"Rangefinder camera","explain":"Camera type focused with a rangefinder (e.g. Leica M, Canon P).","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"slr","ja":["一眼レフ","一眼レフカメラ"],"en":"SLR camera","explain":"Single-lens reflex camera.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"tlr","ja":["二眼レフ","二眼レフカメラ"],"en":"Twin-lens reflex (TLR)","explain":"Twin-lens reflex camera, usually medium format (e.g. Rolleiflex, Mamiya C).","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"mirrorless","ja":["ミラーレス","ミラーレス一眼"],"en":"Mirrorless camera","explain":"Digital mirrorless camera. Often mentioned as the body vintage lenses are tested on via adapter.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"chuuban","ja":["中判","中判カメラ"],"en":"Medium format","explain":"Medium-format camera, usually 120 film.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"film_camera","ja":["フィルムカメラ"],"en":"Film camera","explain":"Film camera.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"compact","ja":["コンパクトカメラ","フィルムコンパクト"],"en":"Compact camera","explain":"Compact point-and-shoot camera. Electronics failures are common and hard to repair.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"jabara","ja":["蛇腹"],"en":"Bellows","explain":"Folding-camera bellows. Check for pinholes that cause light leaks.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"makiage","ja":["巻き上げ","巻上げ","巻き上げレバー"],"en":"Film advance","explain":"Film advance lever/knob.","genre":["camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"makiage_fuku","ja":["巻き上げ不良","巻き上げできない","巻き上げ不可","巻き上げが重い"],"en":"Film advance fault","explain":"Film advance is stuck, rough or incomplete. Needs repair.","genre":["camera"],"category":"defect","risk":"high","reviewed":true},{"id":"denchishitsu","ja":["電池室","電池ボックス"],"en":"Battery compartment","explain":"Battery compartment. Look for corrosion from old leaked batteries.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"jissha","ja":["実写確認","実写確認済み","実写確認済"],"en":"Test photos checked","explain":"Real photos were taken to check function. Stronger than a visual check; ask to see samples.","genre":["camera"],"category":"condition","risk":"positive","reviewed":true},{"id":"shisha","ja":["試写済み","試写済","テスト撮影済み"],"en":"Test-shot","explain":"Test photos taken (sometimes on a digital body via adapter for lenses). Ask what was tested.","genre":["camera"],"category":"condition","risk":"positive","reviewed":true},{"id":"seisou_zumi","ja":["清掃済み","清掃済","クリーニング済み","クリーニング済"],"en":"Cleaned","explain":"Cleaned by the seller. Usually external or easily reached surfaces only, not a full service.","genre":["camera"],"category":"service","risk":"low","reviewed":true},{"id":"seibi_zumi","ja":["整備済み","整備済","分解整備済み","分解清掃済み"],"en":"Serviced (repaired/adjusted)","explain":"Disassembled and serviced. Ask who did it and whether any warranty applies.","genre":["camera"],"category":"service","risk":"positive","reviewed":true},{"id":"body","ja":["ボディ","ボディー"],"en":"Camera body","explain":"The camera body, without lens unless stated.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"body_only","ja":["ボディのみ","ボディーのみ","ボディ単体"],"en":"Body only (no lens)","explain":"Camera body only; no lens included.","genre":["camera"],"category":"accessory","risk":"info","reviewed":true},{"id":"lens_only","ja":["レンズのみ","レンズ単体"],"en":"Lens only","explain":"Lens only, no camera body.","genre":["camera"],"category":"accessory","risk":"info","reviewed":true},{"id":"lens_cap","ja":["レンズキャップ","フロントキャップ","リアキャップ","ボディキャップ"],"en":"Lens / body caps","explain":"Front, rear or body cap. Cheap to replace but nice for collectors.","genre":["camera"],"category":"accessory","risk":"info","reviewed":true},{"id":"hood","ja":["フード","レンズフード"],"en":"Lens hood","explain":"Lens hood. Original maker hoods can be valuable for some vintage lenses.","genre":["camera"],"category":"accessory","risk":"info","reviewed":true},{"id":"mount","ja":["マウント"],"en":"Lens mount","explain":"Lens mount system (e.g. Mマウント = Leica M mount, Fマウント = Nikon F mount). Check compatibility with your camera.","genre":["camera"],"category":"part","risk":"info","reviewed":true},{"id":"harikawa","ja":["貼り革","貼革","張り革"],"en":"Leatherette covering","explain":"Body covering. Peeling or missing leatherette is cosmetic and can be replaced.","genre":["camera"],"category":"part","risk":"low","reviewed":true},{"id":"dial","ja":["文字盤","ダイヤル","ダイアル"],"en":"Dial","explain":"The watch face. Originality of the dial is a major value factor for vintage watches.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"redial","ja":["リダン","リダン文字盤","リダイヤル","文字盤書き換え","書き換え文字盤"],"en":"Redial (refinished dial)","explain":"Dial repainted/reprinted. Greatly lowers collector value; fake vintage watches often use redials.","genre":["watch"],"category":"authenticity","risk":"high","reviewed":true},{"id":"shagai_mojiban","ja":["社外文字盤"],"en":"Aftermarket dial","explain":"Non-original dial from a third party. Not original to the watch; lowers value considerably.","genre":["watch"],"category":"authenticity","risk":"high","reviewed":true},{"id":"dial_shimi","ja":["文字盤シミ","文字盤のシミ","文字盤劣化"],"en":"Dial spots / ageing","explain":"Spots or deterioration on the dial. Cosmetic, but restoring it would mean a redial.","genre":["watch"],"category":"defect","risk":"medium","reviewed":true},{"id":"tropical","ja":["トロピカルダイヤル","トロピカル文字盤"],"en":"Tropical dial","explain":"Dial that has faded to brown with age. Some collectors value it; also faked.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"yakou","ja":["夜光","夜光塗料","ルミノバ","トリチウム"],"en":"Lume","explain":"Luminous paint on dial and hands. Original aged lume matching between dial and hands is valued.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"yakou_repaint","ja":["夜光再塗布","夜光塗り直し","夜光入れ直し"],"en":"Relumed","explain":"Lume has been reapplied. Not original; lowers collector value.","genre":["watch"],"category":"part","risk":"medium","reviewed":true},{"id":"hari","ja":["針","時針","分針","秒針"],"en":"Hands","explain":"Watch hands. Check they are original and that the lume matches the dial.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"fuubou","ja":["風防"],"en":"Crystal","explain":"The watch glass/crystal.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"fuubou_ware","ja":["風防割れ","風防ヒビ","風防欠け"],"en":"Cracked crystal","explain":"Crystal is cracked or chipped. Allows moisture and dust in; needs replacement soon.","genre":["watch"],"category":"defect","risk":"high","reviewed":true},{"id":"sapphire","ja":["サファイア","サファイアガラス","サファイアクリスタル"],"en":"Sapphire crystal","explain":"Scratch-resistant sapphire crystal.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"acrylic","ja":["プラ風防","アクリル風防","プラスチック風防"],"en":"Acrylic (plastic) crystal","explain":"Plastic crystal common on vintage watches. Scratches easily but can be polished out.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"mineral","ja":["ミネラルガラス"],"en":"Mineral glass","explain":"Hardened mineral glass crystal.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"bezel","ja":["ベゼル"],"en":"Bezel","explain":"The ring around the crystal. On tool watches, check it is original and turns properly.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"ryuzu","ja":["リューズ","竜頭","龍頭","りゅうず"],"en":"Crown","explain":"Winding/setting crown. A non-original crown can affect water resistance and value.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"junsei_ryuzu","ja":["純正リューズ"],"en":"Original-maker crown","explain":"Crown made by the watch's manufacturer.","genre":["watch"],"category":"part","risk":"positive","reviewed":true},{"id":"shagai_ryuzu","ja":["社外リューズ","非純正リューズ"],"en":"Aftermarket crown","explain":"Third-party replacement crown. Lowers originality and may compromise water resistance.","genre":["watch"],"category":"part","risk":"medium","reviewed":true},{"id":"movement","ja":["ムーブメント","ムーヴメント"],"en":"Movement","explain":"The watch mechanism. Ask for a photo; mismatched movements are a sign of a franken watch.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"caliber","ja":["キャリバー","Cal."],"en":"Calibre (movement model)","explain":"Movement model number. Check it matches the reference.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"jidoumaki","ja":["自動巻き","自動巻","オートマチック"],"en":"Automatic","explain":"Self-winding mechanical movement.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"temaki","ja":["手巻き","手巻"],"en":"Hand-wound","explain":"Manual-wind mechanical movement; must be wound daily.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"quartz","ja":["クオーツ","クォーツ"],"en":"Quartz","explain":"Battery-powered quartz movement. Old battery leakage can damage the movement.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"zenmai","ja":["ゼンマイ","主ゼンマイ"],"en":"Mainspring","explain":"The spring that powers a mechanical movement.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"zenmai_kire","ja":["ゼンマイ切れ"],"en":"Broken mainspring","explain":"Mainspring is broken, so the watch won't run. Repairable, but needs a watchmaker.","genre":["watch"],"category":"defect","risk":"high","reviewed":true},{"id":"nissa","ja":["日差"],"en":"Daily rate (sec/day)","explain":"Seconds gained or lost per day. For vintage mechanical watches, roughly ±30 s/day is a common rough tolerance (varies by model); much more suggests a service is due.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true,"exclude_next":["し"]},{"id":"seido","ja":["精度"],"en":"Accuracy","explain":"Timekeeping accuracy. Ask how it was measured (timegrapher vs. a short check).","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"tomaru","ja":["止まる","止まります","時々止まる","止まることがあります","止まる事があります"],"en":"Stops (intermittently)","explain":"The watch stops sometimes. Usually needs a service; can be a sign of worn or dirty parts.","genre":["watch"],"category":"defect","risk":"high","reviewed":true},{"id":"kadouhin","ja":["稼働品","稼動品","稼働中","稼動中","稼働確認済み"],"en":"Running","explain":"The watch was running when listed. Says nothing about accuracy or service history.","genre":["watch"],"category":"condition","risk":"positive","reviewed":true},{"id":"oh","ja":["オーバーホール","OH","O/H"],"en":"Overhaul (service)","explain":"Full service of a movement or mechanism. Read whether it was done, needed, or recommended.","genre":["camera","watch"],"category":"service","risk":"info","reviewed":true},{"id":"oh_rekifumei","ja":["OH歴不明","オーバーホール歴不明","OH時期不明"],"en":"Service history unknown","explain":"No known service record. Budget for an overhaul for a vintage mechanical watch.","genre":["watch"],"category":"service","risk":"medium","reviewed":true},{"id":"kenma","ja":["研磨","研磨済み","ポリッシュ","新品仕上げ"],"en":"Polished / refinished","explain":"Case was polished. Removes scratches but also metal, softening edges and lowering collector value.","genre":["watch"],"category":"condition","risk":"medium","reviewed":true},{"id":"mikenma","ja":["未研磨","未研磨品"],"en":"Unpolished","explain":"Case has never been polished; original edges intact. Valued by collectors.","genre":["watch"],"category":"condition","risk":"positive","reviewed":true},{"id":"bracelet","ja":["ブレス","ブレスレット"],"en":"Bracelet","explain":"Metal watch bracelet.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"bracelet_nobi","ja":["ブレス伸び","ブレスの伸び","ブレスレット伸び"],"en":"Bracelet stretch","explain":"Worn links make the bracelet sag. Common on vintage bracelets; cosmetic but reduces value.","genre":["watch"],"category":"defect","risk":"medium","reviewed":true},{"id":"amari_koma","ja":["余りコマ","予備コマ","コマ詰め"],"en":"Spare links / links removed","explain":"Spare bracelet links, or links removed to fit a wrist. Missing links limit the size.","genre":["watch"],"category":"accessory","risk":"info","reviewed":true},{"id":"udemawari","ja":["腕周り"],"en":"Wrist size","explain":"Wrist circumference the bracelet/strap currently fits.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"buckle","ja":["バックル","Dバックル","三つ折れバックル"],"en":"Clasp / buckle","explain":"Bracelet clasp or deployant buckle.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"bijou","ja":["尾錠","美錠"],"en":"Tang buckle","explain":"Pin buckle on a leather strap. Original-maker buckles are sometimes valuable.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"junsei_belt","ja":["純正ベルト","純正バンド","純正ストラップ"],"en":"Original-maker strap","explain":"Strap made by the watch brand.","genre":["watch"],"category":"part","risk":"positive","reviewed":true},{"id":"shagai_belt","ja":["社外ベルト","社外バンド","社外ストラップ"],"en":"Aftermarket strap","explain":"Third-party strap. Normal on vintage watches; affects value little.","genre":["watch"],"category":"part","risk":"low","reviewed":true},{"id":"junsei_bracelet","ja":["純正ブレス","純正ブレスレット"],"en":"Original-maker bracelet","explain":"Bracelet made by the watch brand. Adds value.","genre":["watch"],"category":"part","risk":"positive","reviewed":true},{"id":"shagai_bracelet","ja":["社外ブレス","社外ブレスレット"],"en":"Aftermarket bracelet","explain":"Third-party bracelet. Lowers value compared to an original bracelet.","genre":["watch"],"category":"part","risk":"medium","reviewed":true},{"id":"lug_width","ja":["ラグ幅"],"en":"Lug width","explain":"Distance between the lugs; tells you what strap width fits.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"case_size","ja":["ケース径","ケースサイズ"],"en":"Case diameter","explain":"Case size, usually excluding crown.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"dekaatsu","ja":["デカ厚"],"en":"Big and thick (style)","explain":"Japanese term for oversized, thick watches.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"kokuin","ja":["刻印"],"en":"Engraving / stamp","explain":"Engraved or stamped marks (on caseback, clasp, gold hallmarks). Check they match the model.","genre":["watch"],"category":"authenticity","risk":"info","reviewed":true},{"id":"serial","ja":["シリアル","シリアルナンバー","シリアル番号","製造番号"],"en":"Serial number","explain":"Serial number. Helps date the watch and check it matches papers.","genre":["watch"],"category":"authenticity","risk":"info","reviewed":true},{"id":"guarantee","ja":["ギャランティ","ギャランティカード","ギャランティー","ギャランティーカード"],"en":"Guarantee card / papers","explain":"Brand warranty card. Adds value; check the serial matches the watch.","genre":["watch"],"category":"accessory","risk":"positive","reviewed":true},{"id":"kounen_koukan","ja":["後年交換","後年交換品"],"en":"Replaced later (service part)","explain":"Part replaced at a later date, often a service dial, hands or crown. Not original to the watch.","genre":["watch"],"category":"part","risk":"medium","reviewed":true},{"id":"franken","ja":["寄せ集め","フランケン"],"en":"Franken watch (mixed parts)","explain":"Assembled from parts of different watches. Not a genuine original; value is low.","genre":["watch"],"category":"authenticity","risk":"high","reviewed":true},{"id":"homage","ja":["オマージュ","オマージュウォッチ"],"en":"Homage watch","explain":"Design that copies a famous model under a different brand. Legal but not the original; not collector value.","genre":["watch"],"category":"authenticity","risk":"medium","reviewed":true},{"id":"bousui","ja":["防水"],"en":"Water resistance","explain":"Water resistance. On vintage watches, assume it is not water resistant unless tested.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"seikatsu_bousui","ja":["生活防水"],"en":"Splash resistant","explain":"Everyday water resistance only (splashes, rain). Not for swimming.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"bousui_nashi","ja":["防水性能なし","防水性なし","防水性能はありません","非防水"],"en":"No water resistance","explain":"Not water resistant (or not guaranteed). Keep it away from water.","genre":["watch"],"category":"mechanism","risk":"medium","reviewed":true},{"id":"bousui_kensa","ja":["防水検査済み","防水テスト済み"],"en":"Water resistance tested","explain":"Water resistance was tested.","genre":["watch"],"category":"service","risk":"positive","reviewed":true},{"id":"denchi_koukan","ja":["電池交換"],"en":"Battery replacement","explain":"Battery change; read whether it was done or is needed.","genre":["watch"],"category":"service","risk":"info","reviewed":true},{"id":"denchi_koukan_zumi","ja":["電池交換済み","電池交換済"],"en":"Battery replaced","explain":"New battery fitted. Confirms it may run, but not that it is accurate.","genre":["watch"],"category":"service","risk":"positive","reviewed":true},{"id":"jiki","ja":["磁気帯び"],"en":"Magnetized","explain":"Movement is magnetized, causing fast running. Usually easily fixed by demagnetizing.","genre":["watch"],"category":"defect","risk":"low","reviewed":true},{"id":"date","ja":["デイト"],"en":"Date","explain":"Date complication.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"chrono","ja":["クロノグラフ","クロノ"],"en":"Chronograph","explain":"Stopwatch function. Check that start, stop and reset all work.","genre":["watch"],"category":"mechanism","risk":"info","reviewed":true},{"id":"ss","ja":["SS","ステンレス","ステンレススチール"],"en":"Stainless steel (SS)","explain":"Stainless steel case or bracelet.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"titanium","ja":["チタン","チタニウム"],"en":"Titanium","explain":"Titanium case or bracelet.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"yg","ja":["YG","イエローゴールド"],"en":"Yellow gold (YG)","explain":"Yellow gold. Check whether it is solid (K18/K14) or plated.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"wg","ja":["WG","ホワイトゴールド"],"en":"White gold (WG)","explain":"White gold. Check karat stamps.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"pg","ja":["PG","ピンクゴールド"],"en":"Pink gold (PG)","explain":"Pink gold. Check karat stamps.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"rg","ja":["RG","ローズゴールド"],"en":"Rose gold (RG)","explain":"Rose gold. Check karat stamps.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"k18","ja":["K18","18K","18金"],"en":"18-karat gold","explain":"Solid 18k gold (75%). Look for hallmarks; weight affects value.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"k14","ja":["K14","14K","14金"],"en":"14-karat gold","explain":"Solid 14k gold (58.5%).","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"kinmuku","ja":["金無垢"],"en":"Solid gold","explain":"Solid gold, not plated. Check hallmarks.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"gp","ja":["GP","金メッキ","ゴールドメッキ","ゴールドプレート"],"en":"Gold plated (GP)","explain":"Thin gold plating over base metal. Wears through at edges; much less valuable than solid gold.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"gf","ja":["GF","金張り","ゴールドフィルド"],"en":"Gold filled (GF)","explain":"Thicker gold layer bonded to base metal. More durable than plating but not solid gold.","genre":["watch"],"category":"part","risk":"info","reviewed":true},{"id":"kumori_tori_zumi","ja":["クモリ取り済み","クモリ取り済","くもり取り済み","曇り取り済み","クモリ除去済み"],"en":"Haze cleaned (was hazy)","explain":"The lens had internal haze that was cleaned out. Usually fine, but haze can leave faint coating marks or return; ask for a flashlight photo of the glass.","genre":["camera","lens"],"category":"service","risk":"low","reviewed":true},{"id":"kabi_ato","ja":["カビ跡","カビ痕","カビの跡"],"en":"Mold marks (after cleaning)","explain":"Traces left where mold was cleaned off. Mold etches the coating, so the marks stay. Small spots rarely show in photos; large webs lower contrast.","genre":["camera","lens"],"category":"defect","risk":"medium","reviewed":true},{"id":"kabi_tori_zumi","ja":["カビ取り済み","カビ取り済","カビ除去済み"],"en":"Mold cleaned (was moldy)","explain":"Mold was removed. Mold often leaves etched marks in the coating and can regrow if stored humid; ask whether any marks remain.","genre":["camera","lens"],"category":"service","risk":"low","reviewed":true},{"id":"harigawase","ja":["貼り合わせ面","張り合わせ面","貼り合わせレンズ"],"en":"Cemented elements","explain":"Two glass elements glued together. When the glue fails it is called balsam separation (バルサム切れ, \"balsam separation\") — look for that word nearby.","genre":["camera","lens"],"category":"part","risk":"info","reviewed":true},{"id":"focus_ring","ja":["ピントリング","フォーカスリング","ズームリング"],"en":"Focus / zoom ring","explain":"The ring you turn to focus or zoom. Sellers usually say how it feels: smooth, heavy, or loose.","genre":["camera","lens"],"category":"part","risk":"info","reviewed":true},{"id":"ring_heavy","ja":["ピントリング重い","ピントリングが重い","ピントリング重め","ピントリング硬い","フォーカスリング重い","ズームリング重い","ズームリングが重い","ズームリング重め"],"en":"Focus/zoom ring stiff","explain":"The ring turns stiffly, usually from old, dried grease. Usable but tiring for manual focus; a re-grease service costs extra.","genre":["camera","lens"],"category":"defect","risk":"medium","reviewed":true},{"id":"ring_loose","ja":["ピントリングスカスカ","ヘリコイドスカスカ","ズームリングスカスカ","ヘリコイド軽すぎ"],"en":"Focus/zoom ring too loose","explain":"The ring spins with almost no resistance, often because the grease is gone or it was cleaned without re-greasing. Focus can drift; may have wear inside.","genre":["camera","lens"],"category":"defect","risk":"medium","reviewed":true},{"id":"af_fuuryou","ja":["AF不良","AF不動","AF作動不良","AFが作動しない","オートフォーカス不良"],"en":"Autofocus fault","explain":"Autofocus doesn't work or hunts badly. On modern lenses this is often a motor or circuit fault and repair can cost more than the lens. Treat as manual-focus only.","genre":["camera","lens"],"category":"defect","risk":"high","reviewed":true},{"id":"is_fuuryou","ja":["手ブレ補正不良","手ぶれ補正不良","手振れ補正不良","手ブレ補正が効かない","VR不良","IS不良"],"en":"Image stabilizer fault","explain":"Stabilization (VR/IS/OS) doesn't work or makes noise. The unit is costly to repair; images may be blurry even with it switched off.","genre":["camera","lens"],"category":"defect","risk":"high","reviewed":true},{"id":"tebure_hosei","ja":["手ブレ補正","手ぶれ補正","手振れ補正"],"en":"Image stabilization","explain":"Built-in stabilization (Nikon VR, Canon IS, Sigma OS, in-body IBIS). Ask if it was tested — it's easy to miss when a seller only tries the AF.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"zengo_cap","ja":["前後キャップ","前後キャップ付き","前後キャップ付"],"en":"Front and rear caps","explain":"Both lens caps (front and rear) are included. Minor, but it suggests the lens was stored protected.","genre":["camera","lens"],"category":"accessory","risk":"info","reviewed":true},{"id":"tama_boke","ja":["玉ボケ"],"en":"Bokeh balls","explain":"Out-of-focus point lights rendered as round discs. Sellers mention it as a selling point for fast or old lenses; it is a description, not a condition.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"atom_lens","ja":["アトムレンズ","放射性レンズ","トリウムレンズ"],"en":"Thorium (radioactive) lens","explain":"Some 1950s–70s lenses used thorium glass. Mildly radioactive and turns yellow-brown over time; UV light can reduce the tint. Check shipping rules in your country.","genre":["camera","lens"],"category":"part","risk":"low","reviewed":true},{"id":"mount_gata","ja":["マウントガタ","マウント部ガタ","マウントのガタ","マウント部にガタ","鏡筒ガタ","鏡胴ガタ","鏡筒のガタ","鏡胴のガタ"],"en":"Play in mount / barrel","explain":"The lens wobbles in its mount or the barrel has play. Can cause soft or uneven focus and often points to a drop or worn parts.","genre":["camera","lens"],"category":"defect","risk":"medium","reviewed":true},{"id":"kyoudou","ja":["鏡筒","鏡胴"],"en":"Lens barrel","explain":"The outer tube of the lens. Dents or play in the barrel can mean the lens was dropped.","genre":["camera","lens"],"category":"part","risk":"info","reviewed":true},{"id":"shibori_rendou","ja":["絞り連動","絞り連動ピン","絞り連動レバー"],"en":"Aperture coupling","explain":"The pin or lever that lets the body stop the lens down at the moment of exposure. If it sticks, photos come out overexposed.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"shibori_rendou_fuuryou","ja":["絞り連動不良","絞り連動せず","絞りが連動しない","絞り連動NG"],"en":"Aperture coupling fault","explain":"The body can't close the aperture properly, so shots taken at small apertures come out overexposed. Needs repair.","genre":["camera","lens"],"category":"defect","risk":"high","reviewed":true},{"id":"shibori_fudou","ja":["絞り不動","絞り動かず","絞り固着","絞りが動かない"],"en":"Aperture stuck","explain":"The aperture blades don't move. Often oil on the blades or a broken spring; the lens is only usable at one opening until repaired.","genre":["camera","lens"],"category":"defect","risk":"high","reviewed":true},{"id":"saitan_kyori","ja":["最短撮影距離"],"en":"Minimum focus distance","explain":"The closest distance the lens can focus. A spec, not a condition.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"kaihou_f","ja":["開放F値","開放絞り"],"en":"Maximum aperture","explain":"The widest aperture (smallest F number, e.g. F1.4). Many old lenses are slightly soft or glowy wide open; that is normal, not a defect.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"tanshouten","ja":["単焦点","単焦点レンズ"],"en":"Prime lens","explain":"A fixed focal length lens (no zoom).","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"zoom_lens","ja":["ズームレンズ","標準ズーム","望遠ズーム","広角ズーム"],"en":"Zoom lens","explain":"A lens with variable focal length. Check that the zoom ring is smooth and that the lens doesn't extend under its own weight.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"macro_lens","ja":["マクロレンズ"],"en":"Macro lens","explain":"A lens designed for close-up shots. Its long focusing helicoid makes stiff or loose focus more common — read the focus notes.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"old_lens","ja":["オールドレンズ"],"en":"Vintage lens","explain":"Seller term for older (often manual-focus) lenses, usually used on mirrorless bodies via an adapter. Expect some dust or haze; check the optics notes.","genre":["camera","lens"],"category":"mechanism","risk":"info","reviewed":true},{"id":"mount_adapter","ja":["マウントアダプター","マウントアダプタ"],"en":"Mount adapter","explain":"A ring that fits a lens to a different body. Cheap ones may be slightly off, so infinity focus can be affected.","genre":["camera","lens"],"category":"accessory","risk":"info","reviewed":true},{"id":"rubber_nobi","ja":["ラバー伸び","ラバーの伸び","ラバー劣化","ラバーの劣化","ゴムリング伸び","ゴムリングの伸び"],"en":"Grip rubber stretched/aged","explain":"The rubber grip on the focus/zoom ring has stretched or aged and may slip. Cosmetic; replacement rubbers are cheap for common lenses.","genre":["camera","lens"],"category":"defect","risk":"low","reviewed":true},{"id":"filter_waku_dent","ja":["フィルター枠凹み","フィルター枠へこみ","フィルター枠打痕","フィルター枠の凹み","前枠凹み","前枠へこみ"],"en":"Dented filter thread","explain":"The front rim is dented — a sign the lens was dropped or knocked. Filters/hoods may not fit, and internal alignment may be off.","genre":["camera","lens"],"category":"defect","risk":"medium","reviewed":true},{"id":"hogo_filter","ja":["保護フィルター","プロテクトフィルター","レンズプロテクター"],"en":"Protective filter","explain":"A clear filter screwed on the front to protect the glass. Optics notes may be about the filter, not the lens; ask if they checked with it removed.","genre":["camera","lens"],"category":"accessory","risk":"info","reviewed":true},{"id":"lens_contact","ja":["接点不良","レンズ通信不良","レンズ通信エラー","通信エラー表示"],"en":"Contact / communication fault","explain":"Electrical contacts don't connect reliably. On lenses, the body can't talk to the lens (aperture or AF errors). Cleaning sometimes fixes it; often needs repair.","genre":["camera","lens"],"category":"defect","risk":"high","reviewed":true},{"id":"ten_kizu","ja":["点キズ","点傷"],"en":"Pinpoint marks","explain":"Tiny dot-like marks, usually on lens glass. A few rarely show in photos; many on the rear element matter more than on the front.","genre":["camera","lens"],"category":"defect","risk":"low","reviewed":true},{"id":"molt_koukan_zumi","ja":["モルト交換済み","モルト交換済","モルト張り替え済み","モルト貼り替え済み","モルト張替済み","モルト張替え済み"],"en":"Light seals replaced","explain":"The foam light seals were replaced. Good sign on old film bodies: rotten seals are the main cause of light leaks.","genre":["camera","film_camera"],"category":"service","risk":"positive","reviewed":true},{"id":"denchishitsu_fushoku","ja":["電池室腐食","電池室に腐食","電池室の腐食","電池室液漏れ","電池室に液漏れ","電池室に液漏れ跡","電池ボックス腐食"],"en":"Battery compartment corrosion","explain":"A leaked battery corroded the contacts. Light cases clean up; heavy ones break wiring, killing the meter or an electronic shutter.","genre":["camera","film_camera"],"category":"defect","risk":"high","reviewed":true},{"id":"self_timer","ja":["セルフタイマー"],"en":"Self-timer","explain":"Delayed shutter release. On old mechanical bodies the timer is often sticky; minor unless you need it.","genre":["camera","film_camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"self_timer_fudou","ja":["セルフタイマー不動","セルフタイマー不良","セルフタイマー動かず","セルフ不動"],"en":"Self-timer doesn't work","explain":"The self-timer is broken. Usually doesn't affect normal shooting, but on some bodies a jammed timer can block the shutter.","genre":["camera","film_camera"],"category":"defect","risk":"low","reviewed":true},{"id":"finder_kumori","ja":["ファインダークモリ","ファインダーくもり","ファインダー曇り","ファインダー内クモリ","ファインダー内くもり","ファインダー内曇り"],"en":"Viewfinder haze","explain":"The viewfinder looks hazy. On an SLR it doesn't affect photos; on a rangefinder it can make the focus patch hard to see.","genre":["camera","film_camera"],"category":"defect","risk":"low","reviewed":true},{"id":"slow_governor","ja":["スローガバナー"],"en":"Slow-speed governor","explain":"The clockwork that times slow shutter speeds (1/30s and slower). If it sticks, slow speeds hang or run long — read alongside 'スロー粘り' (sticky slow speeds).","genre":["camera","film_camera"],"category":"part","risk":"info","reviewed":true},{"id":"denshi_shutter","ja":["電子シャッター","電子制御シャッター"],"en":"Electronic shutter","explain":"Film bodies: an electronically timed shutter — no battery, no shutter (often one backup speed only). Digital bodies: the silent sensor-readout shutter.","genre":["camera","film_camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"kikai_shutter","ja":["機械式シャッター","メカシャッター","メカニカルシャッター"],"en":"Mechanical shutter","explain":"Spring-driven shutter that fires without a battery. On digital bodies, 'メカシャッター' (mechanical shutter) is the physical shutter (its count matters for wear).","genre":["camera","film_camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"denchi_fuyou","ja":["電池不要","電池なしで動作","電池なしでも動作","電池無しで動作"],"en":"Works without battery","explain":"The camera (usually its shutter) works without a battery. A built-in meter, if any, still needs one.","genre":["camera","film_camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"film_shitsu","ja":["フィルム室"],"en":"Film chamber","explain":"The space behind the back door where the film runs. Look for rust, corrosion, scratches on the rails, or crumbling seal foam.","genre":["camera","film_camera"],"category":"part","risk":"info","reviewed":true},{"id":"atsuban","ja":["圧板","フィルム圧板"],"en":"Pressure plate","explain":"The plate on the back door that holds film flat. Dents or rust can scratch film or soften focus.","genre":["camera","film_camera"],"category":"part","risk":"info","reviewed":true},{"id":"counter_fudou","ja":["フィルムカウンター不動","フィルムカウンター不良","カウンター不動","カウンター不良"],"en":"Frame counter fault","explain":"The frame counter doesn't advance or reset. You lose track of shots; on some bodies the auto-exposure or winder relies on it.","genre":["camera","film_camera"],"category":"defect","risk":"low","reviewed":true},{"id":"makimodoshi","ja":["巻き戻しクランク","巻き戻しノブ","巻戻しクランク","巻き戻しレバー"],"en":"Rewind crank","explain":"The crank/knob used to wind the film back into the canister.","genre":["camera","film_camera"],"category":"part","risk":"info","reviewed":true},{"id":"makimodoshi_fuuryou","ja":["巻き戻し不良","巻き戻しできない","巻き戻し不可","巻戻し不良"],"en":"Rewind fault","explain":"Film (or tape) can't be rewound. On a camera you'd have to open the back in a dark bag to save the roll. Needs repair.","genre":["camera","film_camera"],"category":"defect","risk":"high","reviewed":true},{"id":"kousen_more","ja":["光線漏れ","光漏れ"],"en":"Light leak","explain":"Stray light reaches the film, leaving streaks or fogging — usually from rotten seals or a damaged back. On a digital screen, 光漏れ (\"light leak\") means backlight bleed.","genre":["camera","film_camera"],"category":"defect","risk":"high","reviewed":true},{"id":"mirror_fault","ja":["ミラー落ち","ミラーが戻らない","ミラー戻らず","ミラーアップしたまま","ミラーが上がったまま"],"en":"Mirror stuck or fallen","explain":"The SLR mirror didn't return after firing, or came unglued and fell. The viewfinder goes black; needs repair.","genre":["camera","film_camera"],"category":"defect","risk":"high","reviewed":true},{"id":"mirror_rekka","ja":["ミラー劣化","ミラーの劣化","ミラー剥がれ","ミラー腐食"],"en":"Mirror silvering worn","explain":"The reflective coating on the SLR mirror has spots or flaking. Dims the viewfinder but does not affect photos.","genre":["camera","film_camera"],"category":"defect","risk":"low","reviewed":true},{"id":"shutter_speed_zure","ja":["シャッター速度ズレ","シャッタースピードズレ","シャッター速度が不正確","高速不良","低速不良"],"en":"Shutter speeds inaccurate","explain":"Some speeds run too fast or slow, causing over/underexposure. Common on unserviced bodies; negative film tolerates small errors, slide film doesn't.","genre":["camera","film_camera"],"category":"defect","risk":"medium","reviewed":true},{"id":"film_format","ja":["35mmフィルム","135フィルム","120フィルム","220フィルム","ブローニー","ブローニーフィルム"],"en":"Film format","explain":"35mm (135) is the common small film; 120/220 'Brownie' roll film is medium format. Check that the format is still easy to buy and process near you.","genre":["camera","film_camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"half_size","ja":["ハーフサイズカメラ","ハーフカメラ","ハーフ判"],"en":"Half-frame camera","explain":"Takes two small frames per 35mm frame (e.g. 72 shots per 36-exposure roll). Lower resolution per shot by design.","genre":["camera","film_camera"],"category":"mechanism","risk":"info","reviewed":true},{"id":"film_inside","ja":["フィルムが入ったまま","フィルム入ったまま","フィルムが入っています","撮影途中のフィルム"],"en":"Film still inside","explain":"A roll is still in the camera. It may be exposed; the seller may not have opened the back to check the film chamber or shutter.","genre":["camera","film_camera"],"category":"seller","risk":"low","reviewed":true},{"id":"ae_fuuryou","ja":["AE不良","AE作動不良","自動露出不良","AE不動"],"en":"Auto-exposure fault","explain":"The automatic exposure mode doesn't work or gives wrong exposures. Manual modes may still work if the body has them.","genre":["camera","film_camera"],"category":"defect","risk":"high","reviewed":true},{"id":"jissha_mikakunin","ja":["実写未確認","試写未確認","試写はしていません","試写していません"],"en":"Not tested with film","explain":"The seller didn't shoot a test roll. Shutter and meter may work, but light leaks, shutter capping or focus errors would only show on film.","genre":["camera","film_camera"],"category":"condition","risk":"medium","reviewed":true},{"id":"kandouhin","ja":["完動品"],"en":"Fully working (claimed)","explain":"Seller claims every function works. Ask what was tested — on cameras, whether all shutter speeds and the meter were checked and film was shot.","genre":["general","camera"],"category":"condition","risk":"positive","reviewed":true}],"review_note":"QC pass 2026-10-08 by Ren (P4 lead, AI): every entry read for meaning, risk level and false-match risk. A native-speaking camera/watch specialist should re-check before any public release."};
  if (typeof module !== "undefined" && module.exports) module.exports = NS;
})(typeof globalThis !== "undefined" ? globalThis : this);
